import { MeshBasicNodeMaterial, PlaneGeometry, Group, Mesh, DoubleSide, Color } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, float, Fn, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'hub-collection-card-1';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = new THREE.Color(colors.ink ?? '#16161d');
  const paper = new THREE.Color(colors.paper ?? '#e8ecf2');
  const accent = new THREE.Color(colors.accent ?? '#ff2a38');
  const surface = new THREE.Color(colors.surface ?? '#0b0b10');

  const cardW = 2.0;
  const cardH = 1.25;

  // Inner group for any local animation (adapter sets root transform separately)
  const inner = new THREE.Group();
  root.add(inner);

  // --- Engineered gradient + grain frame (backdrop) ---
  const grainFn = Fn(([co]) => {
    const r = fract(sin(co.dot(vec2(12.9898, 78.233))).mul(43758.5453));
    return r;
  });

  const frameMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true, opacity: 0.0 });
  const fuv = uv();
  // vertical engineered gradient: surface (top) -> ink (bottom)
  const gT = smoothstep(float(0.0), float(1.0), fuv.y);
  const grad = mix(vec3(ink), vec3(surface), gT);
  // subtle grain overlay
  const grain = grainFn(fuv.mul(vec2(220.0, 140.0))).sub(0.5).mul(0.035);
  frameMat.colorNode = grad.add(grain);

  const frame = new Mesh(new PlaneGeometry(cardW + 0.12, cardH + 0.12), frameMat);
  frame.position.z = -0.02;
  inner.add(frame);

  // --- Image plane (product shot) ---
  const imgMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true, opacity: 0.0 });
  const imgPlane = new Mesh(new PlaneGeometry(cardW, cardH), imgMat);
  imgPlane.position.z = 0.0;
  inner.add(imgPlane);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    imgMat.map = tex;
    imgMat.needsUpdate = true;
  });

  // --- Accent edge line (signal red, <=10% of frame) ---
  const edgeMat = new MeshBasicNodeMaterial({ color: accent, side: DoubleSide, transparent: true, opacity: 0.0 });
  const edge = new Mesh(new PlaneGeometry(cardW + 0.12, 0.018), edgeMat);
  edge.position.set(0, -(cardH / 2) - 0.06, 0.01);
  inner.add(edge);

  // --- Subtle fade-in entrance (static composition, no movement) ---
  const tl = gsap.timeline();
  tl.to(frameMat, { opacity: 1.0, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(imgMat, { opacity: 1.0, duration: 0.6, ease: 'power2.out' }, 0.08);
  tl.to(edgeMat, { opacity: 1.0, duration: 0.5, ease: 'power2.out' }, 0.25);

  // --- Apply cinematic primitives (none expected, but honor config) ---
  const primCleanups = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const r = ctx.primitives[p.name](inner, p.params ?? {});
      if (r && r.cleanup) primCleanups.push(r.cleanup);
    }
  }

  // --- Event handlers (none per spec) ---
  root.userData.handlers = {};

  // --- Cleanup ---
  root.userData.cleanup = () => {
    tl.kill();
    frameMat.dispose();
    imgMat.dispose();
    edgeMat.dispose();
    frame.geometry.dispose();
    imgPlane.geometry.dispose();
    edge.geometry.dispose();
    primCleanups.forEach((c) => c && c());
  };

  return root;
}
